#!/usr/bin/env node
// Standalone mandatory conformance gate, deliberately outside *.test.mjs.
// Synthetic fixtures exercise the SAME engine; they approve no original source.
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {chmod, lstat, mkdir, mkdtemp, readFile, realpath, rm, writeFile} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {performance} from 'node:perf_hooks';
import {setTimeout as delay} from 'node:timers/promises';
import {runPythonPartitions, runPythonPartitionConformance} from '../tests/helpers/partitioned-python.mjs';

const FIXTURE_NAME='ci-python-partition-conformance.py';
const FIXTURE_SHA='497a0a682c563c0152667be174ee6c9959e64a7ee6a3bd478b3ed258c27df4da';
const PRODUCTION_DRIVER_SHA='e8b89a5aed517be5c1303ca135f9a4964ee58d451444e2e83090a4f363b128f3';
const FIXTURE_SOURCE="#!/usr/bin/env python3
"""Owned synthetic protocol fixture; NEVER an original-source acceptance test.

This exact source is embedded in check-python-partitions.mjs. The controller
pins its SHA256 and fixes argv, suite, case enum, and short fixture budgets.
It uses real unittest discovery, callbacks, subtests, and class cleanups.
"""
import argparse
import json
import os
from pathlib import Path
import signal
import sys
import time
import unittest

SCHEMA = 'ci-python-partition-record-v1'
PREFIX = 'PARTITION_JSON:'
CASES = (
    'success', 'success-crlf', 'success-subtests', 'discovery-missing', 'discovery-extra',
    'selected-missing', 'selected-duplicate', 'wrong-script', 'wrong-sha',
    'wrong-class', 'wrong-module', 'wrong-pid', 'wrong-schema',
    'wrong-sequence', 'unknown-event', 'missing-terminal',
    'duplicate-terminal', 'wrong-terminal', 'invalid-outcome', 'missing-stop',
    'early-summary', 'failure', 'subtest-failure', 'setup-error',
    'cleanup-error', 'skip', 'expected-failure', 'unexpected-success',
    'nonzero', 'signal', 'early-exit', 'malformed-json', 'unframed',
    'truncated', 'stdout-overflow', 'stderr-overflow', 'child-timeout',
    'peer-failure', 'parent-abort', 'spawn-error', 'cleanup-tool-failure',
)
PLANS = {
    'six-history': {
        'script': 'tests/six_boundary_history_acceptance.py',
        'sha256': '1d360d565fc9f534fe27bca1dee6388f8faad516ff0ae57803aee6a23162aa55',
        'class_name': 'SixHistoryControls',
        'module_name': 'ci_partition_six_history',
        'methods': (
            'test_01_exact_positive_and_explicit_historical_logical_frame',
            'test_02_cached_positive_does_not_hide_any_current_data_mutation',
            'test_03_every_source_runtime_and_parent_proof_refuses_loss_and_tampering',
            'test_04_original_C1_bytes_cannot_replace_actual_future_data',
            'test_05_C1_fixture_tampering_and_symlink_refuse_after_positive',
            'test_06_pure_inverse_preserves_unrelated_mutations_but_complete_gate_refuses_them',
            'test_07_runtime_parent_and_full343_objects_are_mandatory',
        ),
        'heavy_index': 1,
        'cap': 1048576,
    },
    'six-operation-scope': {
        'script': 'tests/six_operation_scope_controls.py',
        'sha256': 'e4bc5488f629b6637a0adec4daf719134abe97ca123897f906da0ac8176ab570',
        'class_name': 'SixOperationScopeControls',
        'module_name': 'ci_partition_six_operation_scope',
        'methods': (
            'test_01_verified_immutable_original_bytes_within_one_operation',
            'test_02_public_gates_reject_active_and_closed_internal_scopes',
            'test_03_exception_closes_and_prevents_escaped_reuse',
            'test_04_new_public_calls_recheck_actual_data_despite_same_size_and_mtime',
            'test_05_mandatory_proofs_are_physical_even_inside_a_valid_operation',
            'test_06_every_original_fixture_is_verified_before_operation_use',
            'test_07_mutation_after_capture_never_survives_the_next_operation',
        ),
        'heavy_index': 3,
        'cap': 262144,
    },
}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--suite', choices=tuple(PLANS), required=True)
    parser.add_argument('--part', choices=('heavy', 'remaining'), required=True)
    parser.add_argument('--case', choices=CASES, required=True)
    args = parser.parse_args()
    plan = PLANS[args.suite]
    pid = os.getpid()
    heavy = args.part == 'heavy'
    case = args.case if heavy or args.case == 'success-crlf' else 'success'
    sequence = 0
    cleanup_done = False
    started, stopped, terminals = [], [], []
    target = plan['methods'][plan['heavy_index']]
    full_target = plan['module_name'] + '.' + plan['class_name'] + '.' + target

    # Fresh exclusive markers are outside stdout and contain no source/user data.
    marker = Path('ci-fixture-' + args.part + '.json')
    pending_marker = marker.with_suffix('.json.tmp')
    with pending_marker.open('x', encoding='ascii') as handle:
        json.dump({'pid': pid, 'part': args.part, 'case': args.case,
                   'platform': sys.platform}, handle, separators=(',', ':'))
    os.replace(pending_marker, marker)

    def raw(text):
        if args.case == 'success-crlf':
            # Actual UTF-8 CRLF bytes on every OS; bypass Windows text newline
            # translation so this never becomes CRCRLF or a platform spoof.
            if not text.endswith('\n'):
                raise RuntimeError('CRLF positive requires a complete record')
            sys.stdout.buffer.write(text[:-1].encode('utf-8') + b'\r\n')
            sys.stdout.buffer.flush()
        else:
            sys.stdout.write(text)
            sys.stdout.flush()

    def emit(event, **fields):
        nonlocal sequence
        row = {'schema': SCHEMA, 'event': event, 'suite': args.suite,
               'part': args.part, 'pid': pid, 'sequence': sequence}
        row.update(fields)
        sequence += 1
        if case == 'wrong-pid' and event == 'discovery':
            row['pid'] += 1
        if case == 'wrong-schema' and event == 'discovery':
            row['schema'] = 'ci-python-partition-record-v0'
        if case == 'wrong-sequence' and event == 'discovery':
            row['sequence'] += 1
        raw(PREFIX + json.dumps(row, ensure_ascii=False,
                                separators=(',', ':')) + '\n')

    def wait_for_peer():
